protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    final long FETCH_DATA_DURATION = 3600000; // Example duration in milliseconds, adjust as necessary

    if (start >= end) {
        throw new IllegalArgumentException("Start time must be before end time.");
    }

    try {
        while (start < end) {
            long newEnd = Math.min(start + FETCH_DATA_DURATION, end);
            timeRanges.add(new TimeRange(start, newEnd));
            start = newEnd;
        }
    } catch (Exception e) {
        throw new RuntimeException("Error building time ranges", e);
    }

    return timeRanges;
}

