private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    if (size == 0) {
        return; // No need to enlarge if no additional space is required
    }
    int currentCapacity = (data == null) ? 0 : data.length;
    int requiredCapacity = currentCapacity + size;
    if (requiredCapacity > currentCapacity) {
        int newCapacity = (currentCapacity == 0) ? 64 : currentCapacity * 2;
        while (newCapacity < requiredCapacity) {
            newCapacity *= 2;
        }
        byte[] newData = new byte[newCapacity];
        if (data != null) {
            System.arraycopy(data, 0, newData, 0, currentCapacity);
        }
        data = newData;
    }
}

