final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    try {
        if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
            throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
        }
        if (charBuffer == null) {
            throw new IllegalArgumentException("Character buffer cannot be null");
        }

        int utf8Length = (classFileBuffer[constantPoolEntryIndex] & 0xFF) << 8 |
                         (classFileBuffer[constantPoolEntryIndex + 1] & 0xFF);
        int utf8Index = constantPoolEntryIndex + 2;
        int charIndex = 0;

        while (utf8Index < constantPoolEntryIndex + 2 + utf8Length) {
            int byte1 = classFileBuffer[utf8Index++] & 0xFF;
            if (byte1 < 0x80) {
                charBuffer[charIndex++] = (char) byte1;
            } else if ((byte1 & 0xE0) == 0xC0) {
                int byte2 = classFileBuffer[utf8Index++] & 0xFF;
                charBuffer[charIndex++] = (char) ((byte1 & 0x1F) << 6 | (byte2 & 0x3F));
            } else if ((byte1 & 0xF0) == 0xE0) {
                int byte2 = classFileBuffer[utf8Index++] & 0xFF;
                int byte3 = classFileBuffer[utf8Index++] & 0xFF;
                charBuffer[charIndex++] = (char) ((byte1 & 0x0F) << 12 | (byte2 & 0x3F) << 6 | (byte3 & 0x3F));
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
        }

        return new String(charBuffer, 0, charIndex);
    } catch (ArrayIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid UTF-8 data at index: " + constantPoolEntryIndex, e);
    }
}

