    do {
        vertexList.add(currentVertex);
        currentVertex = vertexPredecessors.get(currentVertex);
    } while (currentVertex != null && !vertexList.contains(currentVertex));

    if (!vertexList.contains(currentVertex)) {
        throw new IllegalArgumentException("Tour is not a valid path in the graph");
    }

    int cycleStartIndex = vertexList.indexOf(currentVertex);
    List<V> cycleVertexList = vertexList.subList(cycleStartIndex, vertexList.size());
    List<E> cycleEdgeList = new ArrayList<>();
    double totalWeight = 0.0;

    for (int i = 0; i < cycleVertexList.size() - 1; i++) {
        V source = cycleVertexList.get(i);
        V target = cycleVertexList.get(i + 1);
        E edge = graph.getEdge(source, target);
        if (edge == null) {
            throw new IllegalArgumentException("Tour contains an edge not present in the graph");
        }
        cycleEdgeList.add(edge);
        totalWeight += edgeWeights.get(edge);
    }

    // Add the last edge to complete the cycle
    V source = cycleVertexList.get(cycleVertexList.size() - 1);
    V target = cycleVertexList.get(0);
    E edge = graph.getEdge(source, target);
    if (edge == null) {
        throw new IllegalArgumentException("Tour contains an edge not present in the graph");
    }
    cycleEdgeList.add(edge);
    totalWeight += edgeWeights.get(edge);

    return new GraphPathImpl<>(graph, startVertex, cycleEdgeList, totalWeight);
