public int readTag() throws IOException {
    if (inputStream == null) {
        throw new IOException("Input stream is not initialized.");
    }
    int firstByte = inputStream.read();
    if (firstByte == -1) {
        return 0; // End of file reached
    }
    if ((firstByte & 0x80) == 0) {
        return firstByte; // Single byte tag
    }
    int result = firstByte & 0x7F;
    int shift = 7;
    while (true) {
        int b = inputStream.read();
        if (b == -1) {
            throw new IOException("Unexpected end of stream while reading tag.");
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
        if (shift >= 32) {
            throw new IOException("Malformed tag: too long.");
        }
    }
    return result;
}

