public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("File must be a valid existing file.");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges must be non-null and non-empty.");
    }

    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Assuming each line represents a thread snapshot in a specific format
            // For example: "timestamp,threadId,state,stackTrace"
            String[] parts = line.split(",");
            if (parts.length < 4) {
                continue; // Skip malformed lines
            }

            try {
                long timestamp = Long.parseLong(parts[0]);
                int threadId = Integer.parseInt(parts[1]);
                String state = parts[2];
                String stackTrace = parts[3];

                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, threadId, state, stackTrace);

                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range.getStart() <= timestamp && timestamp <= range.getEnd()) {
                        snapshots.add(snapshot);
                        break;
                    }
                }
            } catch (NumberFormatException e) {
                // Skip lines with invalid numeric values
                continue;
            }
        }
    }
    return snapshots;
}
